#!/usr/bin/env python3
"""Write the generated files of arith/<function>/harness/ (arith brief 139a, owner decision 24): the packaged verification harness a user reruns against their
own instance after integration. Handwritten and committed in each harness folder: assertions.sv, chk_top.sv, coverage.yaml (and mac_ref.sv for the MAC).
Generated here, from the repository's own files, so the harness cannot drift from the bench the repository tests: model.py, bench.py, harness_common.py,
<function>_cocotb.py, run_harness.py, README.md.

    python3 -m arith.tools.gen_harness [adder multiplier mac] [--check]"""
from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

from arith.tools import arith_common as ac

EXAMPLE = {"adder": ('"WIDTH": 32', 0), "multiplier": ('"WA": 18, "WB": 18, "SIGNED": 1', 3), "mac": ('"WA": 16, "WB": 16, "LANES": 1, "ACCW": 40, "SIGNED": 1', 3),
           "exp2": ('"IW": 12, "OW": 12, "SB": 5', 2), "log2": ('"IW": 12, "OW": 12, "SB": 5', 2), "sincos": ('"PH": 14, "OW": 14, "SB": 5', 2),
           "atan2_mag": ('"W": 12, "PH": 12, "NIT": 14, "G": 12', 16),
           "fp_add": ('"EXP": 8, "MAN": 23, "SUBNORM": 1, "STAGES": 3', 3), "fp_mul": ('"EXP": 8, "MAN": 23, "SUBNORM": 1, "STAGES": 3', 3),
           "fp_fma": ('"EXP": 8, "MAN": 23, "SUBNORM": 1, "STAGES": 4', 4)}
EXAMPLE_VARIANT = {"exp2": "lerp", "log2": "lerp", "sincos": "lerp", "atan2_mag": "cordic"}


def common_text() -> str:
    src = (ac.ARITH / "tools" / "arith_common.py").read_text()
    i = src.index("def edge_values")
    return ('"""Stimulus helpers of the harness (copied from arith/tools/arith_common.py by arith/tools/gen_harness.py)."""\nfrom __future__ import annotations\n\nimport random\n\n\n' + src[i:])


def cocotb_text(fn: str) -> str:
    t = (ac.ARITH / fn / "tests" / f"{fn}_cocotb.py").read_text()
    t = t.replace("from arith.fp_common import fp_ref", "import fp_ref")
    t = t.replace(f"from arith.{fn} import model", "import model").replace("from arith.tools import arith_common as ac", "import harness_common as ac").replace("from arith.tools import bench", "import bench")
    t = t.replace("arith/", "").replace("arith.", "")
    return t


def readme(fn: str) -> str:
    s = ac.load_spec(fn)
    ex, lat = EXAMPLE[fn]
    L = [f"# Verification harness for the {fn} ({s['title']})", "",
         f"Generated by `python -m arith.tools.gen_harness` (arith brief {ac.brief_of(fn)}); the handwritten parts are `assertions.sv`, `chk_top.sv` and `coverage.yaml`. "
         "This folder is a deliverable: rerun it against your own instance after you integrate or change the block. It needs nothing else from the repository.", "",
         "## What is in it", "",
         "| File | What |", "|---|---|",
         "| `model.py` | the bit-exact model of the specification ([../spec.md](../spec.md)), in Python integers" + (" (it calls `fp_ref.py`, the exact-rational reference; the checker uses `fpx_ref.sv`, the specification as wide integer RTL)" if fn.startswith("fp_") else "") + " |",
         f"| `bench.py`, `{fn}_cocotb.py`, `harness_common.py` | the cocotb bench: drives one vector per clock (exhaustive at small widths; edge values, runs of ones and random inputs at large ones) and compares every output bit with the model, allowing for your latency |",
         ("| `assertions.sv` | a passive SIMULATION checker with the exact function in real arithmetic (the simulator's `$sin`, `$atan2`, `$pow`, `$ln`, `$hypot`) and an error bound in last places; put it beside your instance in your own bench or in the simulator of your choice; its `errors` counter is 0 when the instance is within the bound |"
          if fn in ac.ELEMENTARY else
          "| `assertions.sv` | a passive SystemVerilog checker with the specification as plain wide arithmetic; put it beside your instance in your own bench or in the simulator of your choice; its `errors` counter is 0 when the instance conforms |"),
         "| `chk_top.sv` | your instance with the checker beside it, used by `run_harness.py --checker` |",
         "| `coverage.yaml` | the coverage targets (bins over the inputs and the model's results, with minimum hit counts) that the stimulus must reach; `run_harness.py` fails if one is missed |",
         "| `run_harness.py` | the standalone runner (Icarus Verilog + cocotb) |", "",
         "## Running it against your instance", "",
         "Needs `iverilog`, Python 3, `pip install cocotb==2.0.1 pyyaml`.", "", "```",
         f"python3 run_harness.py --rtl my_{fn}.sv --top my_module --params '{{{ex}}}' --latency {lat} " + (f"--variant {EXAMPLE_VARIANT[fn]} " if fn in EXAMPLE_VARIANT else "") + "--mode both --checker", "```", "",
         "- `--top` must have the ports listed in the specification under the same names, and the parameters you pass in `--params` (the harness needs the widths and signedness to build the model).",
         "- `--latency` is your instance's latency in clocks. Giving a wrong latency fails the run: that is deliberate, it checks the number.",
         *(["- `--variant` names the variant of this library whose model (`model.py`, `model.compute`) your instance is compared with, bit for bit: the variants of this function are not bit-identical to each other, so pass the one yours is, or accept that only the checker's error bound will agree.",
            "- `--err-ulp` sets the checker's error bound in last places; the default is the variant's measured maximum at your parameters plus 0.05 (every input is scanned), or for atan2_mag at W above 7 the maximum over a sample plus 0.25. State your own bound to hold an instance of your own to the accuracy you need."] if fn in ac.ELEMENTARY else []),
         "- `--mode exhaustive` is for small widths only (about 12 operand bits); `randomised` for any width; `both` runs both.",
         "- `--checker` builds your instance next to `assertions.sv`; the run fails if the checker's error counter is not 0. To use the checker in your own bench instead, instantiate it with the same signals as in `chk_top.sv`.",
         "- Exit status 0 means: every vector matched the model, the checker saw no mismatch, and every coverage target was met. `--build-dir` keeps the logs and `coverage.json`.", "",
         "## Interface the harness assumes", ""]
    c = s["contract"]
    L += [f"- Protocol: {c['protocol']}", f"- Throughput: {c['throughput']}", f"- Latency: {c['latency']}", f"- Reset: {c['reset']}", f"- Clock: {c['clock']}", "",
          "Parameter names used by the variants of this library (your instance needs the ones the model uses; the others are ignored by the model):", ""]
    L += [f"- `{k}`: {v['text']}" for k, v in s["parameters"].items()]
    L += ["", "## What it does not check", "",
          "Timing, power, area and clocking (those are Vivado's), behaviour for parameter values outside the ranges in the specification, X-propagation beyond the first compare, and "
          "anything about the surrounding design (handshakes, valid bits, your reset sequencing). A pass shows the instance computes the specified function with the stated latency at the "
          "parameters you ran; run it at each parameter set you instantiate.", ""]
    return "\n".join(L)


def outputs(fn: str) -> dict[Path, str]:
    h = ac.ARITH / fn / "harness"
    run = (ac.ARITH / "tools" / ("run_harness_template_elem.py" if fn in ac.ELEMENTARY else "run_harness_template.py")).read_text().replace("@FN@", fn).replace("@BRIEF@", ac.brief_of(fn))
    ex, lat = EXAMPLE[fn]
    run = run.replace("@EXAMPLE_PARAMS@", ex).replace("@EXAMPLE_LAT@", str(lat)).replace("@EXAMPLE_VARIANT@", f"--variant {EXAMPLE_VARIANT[fn]} " if fn in EXAMPLE_VARIANT else "")
    if fn.startswith("fp_"):                       # the default mode is chosen from the operand bits of all inputs (two for fp_add and fp_mul, three for fp_fma)
        old = ('        bits = sum(v for k, v in params.items() if k in ("WIDTH", "WA", "WB", "LANES")) if FUNCTION != "adder" else 2 * params.get("WIDTH", 99)\n'
               '        mode = "exhaustive" if bits <= (12 if FUNCTION != "adder" else 12) else "randomised"')
        assert old in run
        run = run.replace(old, '        bits = (3 if FUNCTION == "fp_fma" else 2) * (1 + params.get("EXP", 99) + params.get("MAN", 99))      # operand bits in all\n'
                               '        mode = "exhaustive" if bits <= (18 if FUNCTION == "fp_fma" else 16) else "randomised"')
    model = (ac.ARITH / fn / "model.py").read_text()
    extra = {}
    if "from arith.tools import fxlib" in model:           # the elementary-function models share the constant tables of fxlib.py: the harness carries a copy
        model = model.replace("from arith.tools import fxlib", "import fxlib")
        extra[h / "fxlib.py"] = (ac.ARITH / "tools" / "fxlib.py").read_text()
    if fn.startswith("fp_"):                       # the floating-point functions share a reference (Python) and a specification as RTL (for the checker)
        extra[h / "fp_ref.py"] = (ac.ARITH / "fp_common" / "fp_ref.py").read_text()
        extra[h / "fpx_ref.sv"] = (ac.ARITH / "fp_common" / "fpx_ref.sv").read_text()
    return {**extra, h / "model.py": model, h / "bench.py": (ac.ARITH / "tools" / "bench.py").read_text(),
            h / "harness_common.py": common_text(), h / f"{fn}_cocotb.py": cocotb_text(fn), h / "run_harness.py": run, h / "README.md": readme(fn)}


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("functions", nargs="*", default=list(ac.FUNCTIONS))
    ap.add_argument("--check", action="store_true")
    a = ap.parse_args()
    bad = 0
    for fn in a.functions:
        for p, t in outputs(fn).items():
            if a.check:
                if not p.exists() or p.read_text() != t:
                    print("out of date:", p.relative_to(ac.ROOT))
                    bad = 1
            else:
                p.write_text(t)
        if not a.check:
            print("wrote harness of", fn)
    return bad


if __name__ == "__main__":
    sys.exit(main())
